+  final name = _agentNameFromFile(entry.name);
+  if (name == null) return;
+  if (!seen.add(name.toLowerCase())) return;
+  final textResult = await env.readTextFile(entry.path);
+  final text = textResult.valueOrNull;
+  if (text == null) return;
+  final parsed = _parseAgentFile(name, text);
