+    return;
+  }
+  final dirResult = await env.listDir(root.path);
+  final entries = dirResult.valueOrNull;
+  if (entries == null) return;
+  for (final entry in entries) {
+    await _ingestAgentEntry(env, entry, seen, agents, notes);
